(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:16px 20px;display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><span style="font-size:13px;color:#A7A2B6">Best lever</span><b style="font-family:Space Grotesk,sans-serif;font-size:16px;color:#C6F432">In-store launch campaign</b></div></div></div></div>
									<div class="elementor-tab-title elementor-tab-mobile-title" aria-selected="false" data-tab="4" role="tab" tabindex="-1" aria-controls="elementor-tab-content-9824" aria-expanded="false">D2C Subscriptions</div>
